nta.declaration:

/// ----- ** GLOBAL CONSTANTS
/*
    if F != 0, 
    `FaultyNodeNomination`, `FaultyNodeBallot` should be added in System declarations.
*/
const int THRESHOLD_PERCENT = 100; // Quorum Set Agreement Percentage for Quorum Slice Formation (System-wide)
const int N = 5; // total number of nodes
const int F = 0; // total number of faulty nodes
const int V = 1; // maximum number of values in nomination state

const int BOUNDARY = 14;
const int INFINITY = BOUNDARY+1;

// ** states for NominationBallot
const int SCPPrepare = 0;
const int SCPConfirm = 1;
const int SCPExternalize = 2;


/// ------ ** TYPE DEFINITIONS

typedef int[0,N-F-1] n_id;     // node id (0 to n-f-1)
typedef int[N-F,N-1] f_id;     // fault node id (n-f to n-1)
typedef int[0,V-1] v_id;       // value id (0 to v-1)
typedef int[0,N-1] t_id;       // tick id

typedef struct {
    int[0,N] threshold;
    int[0,N] validators[N]; // reserving as many as N, stores ids
} SCPQuorumSet;

// nomination
typedef struct {
    bool voted[V];
    bool accepted[V];
} SCPNominationState;

// ballot
typedef struct {
    int[0,INFINITY] counter;
    bool value[V];
} SCPBallot;

typedef struct {
    /* `curState`
        SCPPrepare = 0;
        SCPConfirm = 1;
        SCPExternalize = 2;
    */
    int[0,2] curState;
    SCPBallot b;
    SCPBallot p;
    SCPBallot pp;
    SCPBallot h;
    SCPBallot c;
} SCPBallotState;


/// ------ ** Node configurations
/// ------- - modify here after change N, F values

// `totalParticipants` incidates # of nodes involved in a decision process.
// Every value is required for a decision process.
const int totalParticipants = N;

const bool NOVALUE[V] = // empty values (no values)
    {false};
const bool ISALLFALSE[V] = // TODO: need to be reviewed for the name
    {false};

SCPQuorumSet qs[N] =
    // N is used as a sentinel value for an empty validator slot.
    // {threshold, {validators[N]}}
    // {0, 1, 2, N, N} → validators = {0, 1, 2}
    {
        {0, {0, 1, 2, N, N}}, // 0
        {0, {0, 1, 2, N, N}}, // 1
        {0, {0, 1, 2, N, N}}, // 2
        {0, {0, 1, 2, 3, N}}, // 3
        {0, {0, 1, 2, N, 4}}  // 4
    };

// * -- Nomination protocol data
SCPNominationState nominationStates[N];

bool higherlayerInput[N][V] =
    // Assumes the values are always correct based on the modeling abstaction level.
    // indicates if a node has a value to be written.
   {{true},
    {true},
    {false},
    {false},
    {false}};

bool nominatedValues[N][V] =
   {{false},
    {false},
    {false},
    {false},
    {false}};

// *-- Ballot protocol data
SCPBallotState ballotStates[N];

bool ballotDone[N] =
    {false, false, false, false, false};

bool tickReady[N] =
    {true, true, true, true, true};

int[0,INFINITY] tickNomination[N] =
    {0, 0, 0, 0, 0};

int[0,INFINITY] tickBallot[N] =
    {0, 0, 0, 0, 0};

int[0,INFINITY] cur_nRound[N] = // current running nomination round states of each node
    {0, 0, 0, 0, 0};

int[0,INFINITY] cur_b_cnt[N] =  // global reference value for the current running b.n
    {0, 0, 0, 0, 0};



/// ----- ** CHANNELS
chan sthNominated[N];
chan nominationDone[N];

chan decisionDone;

chan tickAdvance[N];
chan tickAdvanceDone[N];

/// broadcast channels
broadcast chan consensusSuccess;
broadcast chan consensusFail;
broadcast chan consensusTimeout;
broadcast chan decisionStarted;

broadcast chan tickStart;
broadcast chan tickStop;
broadcast chan tickManagerStart; // for TickTestApp



/// ------ ** METHODS
bool isLessValue(const bool &valueL[V], const bool &valueR[V]) {
    // check if valueL < valueR

    int[-1, V-1] i;

    for (i = V-1; i >= 0; i--) {
        if (valueL[i] == false && valueR[i] == true) {
            return true;
        } else if (valueL[i] == true && valueR[i] == false) {
            return false;
        }
    }
    return false; // valueL == valueR
}

int getTotalValidators(const int[0,N] curNodeID) {
    /*
        parameter: int curNodeID (range: 0 to N)
        return: int

        Count how many validators `curNodeID` has.
    */
    int[0,N] totalValidators = 0;

    for (i : int[0,N-1]) {
        if (qs[curNodeID].validators[i] != N) {
            totalValidators++;
        }
    }
    return totalValidators;
}

/// !!!: temp declaration. need to be reviewed. and consider how to handle the result with faulty nodes.
bool handlingValues[V];
bool isDecisionDone() {
    for (n : n_id) {
        if (handlingValues != NOVALUE && handlingValues != nominatedValues[n])
            return false;
    }
    return true;
}

template.declaration:
bool isDone() {
    for (t : t_id) {
        if (tickReady[t] == true) {
            return false;
        }
    }
    return true;
} // test

void resetTick() {
    for (t : t_id) {
        tickReady[t] = true;
    }
}

int[0,N] cntDecisionDone = 0;

bool hasHigherlayerInput() {
    for (id : int[0,N-1]) {
        if (higherlayerInput[id] != NOVALUE) {
            return true;
        }
    }
    return false;
}

void clearInputs(const bool &value[V]) {
    for (v : v_id) {
        if (value[v]) {
            for (id : int[0,N-1]) {
                higherlayerInput[id][v] = 0;
            }
        }
    }
}

void doSuccess() {
    clearInputs(ballotStates[0].c.value);
}

bool isAllAgreedLocal(int[0,N-1] nID) {
    bool value[V] = NOVALUE;

    int[0,N] validatorID;

    for (n : n_id) {
        validatorID = qs[nID].validators[n];

        if (validatorID != N) {
            if (value == NOVALUE) {
                value = nominatedValues[validatorID];
            } else {
                if (nominatedValues[validatorID] != value) {
                    return false;
                }
            }
        }
    }

    return true;
}

void resetNominationState() {
    /*
        A method to reset nomination state
        when a state goes back to `StartNomination`
    */
    cur_nRound[myID] = 0;
    tickNomination[myID] = 0;

    for (v : v_id) {
        nominatedValues[myID][v] = false;
        nominationStates[myID].voted[v] = false;
        nominationStates[myID].accepted[v] = false;
    }
}

void initNominationState() {
    /*
        A method to init nomination state
        when a state starts from `StartNomination` to `NominationStarted`
    */
    int[0,N] totalValidators = getTotalValidators(myID);

    if (qs[myID].threshold == 0) { 
        // update a threshold in `qs` for nodeID (the template parameter)
        int thr_numerator = totalValidators * THRESHOLD_PERCENT;
        qs[myID].threshold = (thr_numerator % 100 == 0) 
                                        ? thr_numerator/100 
                                        : thr_numerator/100 + 1;
    }
}

void processMessageNomination(bool hasNominatedValues) {
    int[0,N] cntValues = 0; // node count
    int[0,N] cntValues_qs = 0; // node count in quorum set

    SCPQuorumSet myQuorumSet = qs[myID];

    int[0,N] validatorID;
    int[0,N] nestedValidatorID;

    // blocking threshold check for accept nomination
    for (v : v_id) {
        cntValues = 0;

        // how many validators have accepted on `v`
        for (id : int[0,N-1]) {
            validatorID = myQuorumSet.validators[id];

            if (validatorID != N && validatorID != myID
                && nominationStates[validatorID].accepted[v]) {

                cntValues++; // count for acceptance of my validators on `v`
            }
        }

        // 
        if (cntValues > (getTotalValidators(myID) - myQuorumSet.threshold) // blocking threshold
            && !nominationStates[myID].accepted[v]) {

            nominationStates[myID].accepted[v] = true;
            nominationStates[myID].voted[v] = false;
        }
    }

    // quorum threshold check for vote nomination
    for (v : v_id) {
        cntValues = 0;

        for (id : int[0,N-1]) {
            validatorID = myQuorumSet.validators[id];

            if (validatorID != N) { 
                // check my validator's quorum slices
                cntValues_qs = 0;
                for (qs_id : int[0,N-1]) {
                    nestedValidatorID = qs[validatorID].validators[qs_id];

                    if (nestedValidatorID != N
                        && (nominationStates[nestedValidatorID].accepted[v]
                            || nominationStates[nestedValidatorID].voted[v])) {
                        cntValues_qs++;
                    }
                }

                if (cntValues_qs >= qs[validatorID].threshold) {
                    cntValues++;
                }
            }
        }

        if (cntValues >= myQuorumSet.threshold
            && !nominationStates[myID].accepted[v]) {
            nominationStates[myID].accepted[v] = true;
            nominationStates[myID].voted[v] = false;
        }
    }

    // quorum threshold check for accept nomination
    for (v : v_id) {
        cntValues = 0;

        for (id : int[0,N-1]) {            
            validatorID = myQuorumSet.validators[id];

            if (validatorID != N) {
                cntValues_qs = 0;

                // check my validator's quorum slices
                for (qs_id : int[0,N-1]) {
                    nestedValidatorID = qs[validatorID].validators[qs_id];

                    if (nestedValidatorID != N 
                        && nominationStates[nestedValidatorID].accepted[v]) {
                            cntValues_qs++;
                    }
                }

                if (cntValues_qs >= qs[validatorID].threshold) {
                    cntValues++;
                }
            }
        }

        if (cntValues >= myQuorumSet.threshold) {
            if (!nominationStates[myID].accepted[v]) {
                nominationStates[myID].accepted[v] = true;
                nominationStates[myID].voted[v] = false;
            }

            if (!nominatedValues[myID][v]) {
                nominatedValues[myID][v] = true;
            }
        }
    }
}

int getHighestPriorityNode(int[0,BOUNDARY] cur_round_in) {
    int[0,N] highest = cur_round_in % getTotalValidators(myID);
    int[0,N] current = 0;

    for (id : int[0,N-1]) {
        if (qs[myID].validators[id] != N) {
            if (current == highest) { 
                return qs[myID].validators[id];
            }
            else {
                current++;
            }
        }
    }

    return myID;
}

void getMyHigherlayerInput() {
    for (v : v_id) {
        if (higherlayerInput[myID][v]
            && !nominationStates[myID].accepted[v]
            && !nominationStates[myID].voted[v]) {
            nominationStates[myID].voted[v] = true;
            /// ----------- !!!
            handlingValues[v] = true;
            return;
        }
    }
}

void doEchoing(int[0,N] nodeIDHighest) {
    /*
        For v-th value,
        if (highest node `voted` or `accepted` on it) and 
            nodeID(current node) has not voted or accepted on it,

        nodeID follows the highest node's decision.
    */
    for (v : v_id) {
        if (
            (nominationStates[nodeIDHighest].accepted[v]
                || nominationStates[nodeIDHighest].voted[v])
            && !nominationStates[myID].accepted[v]
            && !nominationStates[myID].voted[v]
        ) {
            nominationStates[myID].voted[v] = true;
        }
    }
}

void newRound(bool hasNominatedValues) {
    int[0,N] nodeIDHighest;

    // check if itself exists in its quorum set
    if (qs[myID].validators[myID] == myID) {

        // if its nomination tick reaches its current round value
        if (tickNomination[myID] == cur_nRound[myID]) {

            // nomination message passing
            processMessageNomination(hasNominatedValues);

            // mark as proceeding next round
            if (cur_nRound[myID] < BOUNDARY) {
                cur_nRound[myID]++;
            }

            // only if it does not have nominated values
            // if it has some, it won't suggest or vote for new values
            if (!hasNominatedValues) {
                // get a leader
                nodeIDHighest = getHighestPriorityNode(cur_nRound[myID]);
                if (nodeIDHighest == myID) {
                    // if leader is self, get and vote for a higher layer input.
                    getMyHigherlayerInput();
                }
                else {
                    // else, vote for the leader's value
                    doEchoing(nodeIDHighest);
                }
            }
            // reset its nomination tick counter
            tickNomination[myID] = 0;
        }
        // else, increase the tick
        if (tickNomination[myID] < cur_nRound[myID]) {
            tickNomination[myID]++;
        }
    }
}

int[0,N] cntDecisionDone = 0;

bool hasNominatedValues() {
    for (id : int[0,N-1]) {
        if (nominatedValues[id] != NOVALUE) {
            return true;
        }
    }
    return false;
}

void clearInputs(const bool &value[V]) {
    for (v : v_id) {
        if (value[v]) {
            for (id : int[0,N-1]) {
                higherlayerInput[id][v] = 0;
            }
        }
    }
}

void doSuccess() {
    clearInputs(ballotStates[0].c.value);
}

bool isAllAgreedLocal(int[0,N-1] nID) {
    bool value[V] = NOVALUE;

    for (n : n_id) {
        if (qs[nID].validators[n] != N) {
            if (value == NOVALUE) {
                value = ballotStates[qs[nID].validators[n]].c.value;
            } else {
                if (ballotStates[qs[nID].validators[n]].c.value != value) {
                    return false;
                }
            }
        }
    }

    return true;
}

/// ----- ** HELPER FUNCTIONS
void sortArr(int[0,N*3] len, int[0,INFINITY]& arr[N*3]) {
    int[0,N*3] i, j, maxIndex;
    int[0,INFINITY] temp;

    for (i=0; i<len; i++) {
        temp = arr[i];
        maxIndex = i;
        for (j=i+1; j<len; j++) {
            if (temp <= arr[j]) {
                temp = arr[j];
                maxIndex = j;
            }
        }
        arr[maxIndex] = arr[i];
        arr[i] = temp;
    }
}

/// ----- ** Ballot checking bool FUNCTIONS
bool checkAcceptedPrepareQuorum(int[0,N] nodeID, const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;
    bool isVBlocked = false;

    SCPQuorumSet nodeQuorumSet = qs[nodeID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        if (N - id + cntQuorumTH < nodeQuorumSet.threshold) {
            return false;
        }

        validatorID = nodeQuorumSet.validators[id];

        if (validatorID != N) {
            isVBlocked = false;
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                if (
                    ( // p
                        validatorBallotState.p.counter != 0
                        && (validatorBallotState.p.value == candidate.value
                            && validatorBallotState.p.counter >= candidate.counter)
                    )
                    || ( // pp
                        validatorBallotState.pp.counter != 0
                        && (validatorBallotState.pp.value == candidate.value
                            && validatorBallotState.pp.counter >= candidate.counter)
                    )
                ) {
                    if (validatorID != nodeID) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && (validatorBallotState.b.value == candidate.value
                        && validatorBallotState.b.counter >= candidate.counter)) {
                    cntQuorumTH++;
                }
            }
            else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                if ( // p
                    validatorBallotState.p.value == candidate.value
                    && validatorBallotState.p.counter >= candidate.counter
                ) {
                    if (validatorID != nodeID) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && validatorBallotState.b.value == candidate.value) {
                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if ( // c
                    validatorBallotState.c.value == candidate.value
                ) {
                    if (validatorID != nodeID) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && validatorBallotState.c.value == candidate.value) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= nodeQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkAcceptedPrepare(const SCPBallot &candidate) {
    int[0,N] cntVBlockTH = 0;
    int[0,N] cntQuorumTH = 0;

    SCPBallotState myBallotState = ballotStates[myID];
    SCPQuorumSet myQuorumSet = qs[myID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    if (myBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
        if (!(myBallotState.p.value == candidate.value
            && myBallotState.p.counter < candidate.counter)) {
            return false;
        }
    }

    if (myBallotState.pp.counter != 0
        && (myBallotState.pp.counter > candidate.counter
            || (myBallotState.pp.counter == candidate.counter
                && !(isLessValue(myBallotState.pp.value, candidate.value))))) { // myBallotState.pp.value >= candidate.value
        return false;
    }

    if (myBallotState.p.counter != 0
        && (myBallotState.p.value == candidate.value
            && myBallotState.p.counter >= candidate.counter)) {
        return false;
    }

    for (id : int[0,N-1]) {
        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                if (
                    ( // p
                        validatorBallotState.p.counter != 0
                        && (validatorBallotState.p.value == candidate.value
                            && validatorBallotState.p.counter >= candidate.counter)
                    )
                    || ( // pp
                        validatorBallotState.pp.counter != 0
                        && (validatorBallotState.pp.value == candidate.value
                            && validatorBallotState.pp.counter >= candidate.counter)
                    )
                ) {
                    if (validatorID != myID) {
                        cntVBlockTH++;
                    }
                }
            }
            else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                if ( // p
                    validatorBallotState.p.value == candidate.value
                    && validatorBallotState.p.counter >= candidate.counter
                ) {
                    if (validatorID != myID) {
                        cntVBlockTH++;
                    }
                }
            }
            else { /// Phase: SCPExternalize
                if (validatorBallotState.c.value == candidate.value) {
                    if (validatorID != myID) {
                        cntVBlockTH++;
                    }
                }
            }

            if (cntVBlockTH > getTotalValidators(myID) - myQuorumSet.threshold) {
                return true;
            }

            if (checkAcceptedPrepareQuorum(validatorID, candidate)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= myQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptAcceptPrepare(SCPBallot &acceptedBallot, SCPBallot &newMessageBallots[3]) {
    bool isAgreed = false;
    bool hasNewAcceptedPrepare = false;
    SCPBallot tempBallot;

    SCPQuorumSet myQuorumSet = qs[myID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            isAgreed = false;
            tempBallot.counter = 0;
            tempBallot.value = NOVALUE;
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (
                            validatorBallotState.b.value == newMessageBallots[j].value
                            && validatorBallotState.b.counter <= newMessageBallots[j].counter
                        ) {
                            isAgreed = checkAcceptedPrepare(validatorBallotState.b);
                            if (isAgreed) {
                                tempBallot.counter = validatorBallotState.b.counter;
                                tempBallot.value = validatorBallotState.b.value;
                            } else {
                                if (
                                    validatorBallotState.p.counter != 0
                                    && (validatorBallotState.p.value == newMessageBallots[j].value
                                        && validatorBallotState.p.counter <= newMessageBallots[j].counter)
                                ) {
                                    isAgreed = checkAcceptedPrepare(validatorBallotState.p);
                                    if (isAgreed) {
                                        tempBallot.counter = validatorBallotState.p.counter;
                                        tempBallot.value = validatorBallotState.p.value;
                                    } else {
                                        if (
                                            validatorBallotState.pp.counter != 0
                                            && (validatorBallotState.pp.value == newMessageBallots[j].value
                                                && validatorBallotState.pp.counter <= newMessageBallots[j].counter)
                                        ) {
                                            isAgreed = checkAcceptedPrepare(validatorBallotState.pp);
                                            if (isAgreed) {
                                                tempBallot.counter = validatorBallotState.pp.counter;
                                                tempBallot.value = validatorBallotState.pp.value;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (validatorBallotState.c.value == newMessageBallots[j].value) {
                            isAgreed = checkAcceptedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            } else {
                                if (validatorBallotState.p.counter < newMessageBallots[j].counter) {
                                    tempBallot.counter = validatorBallotState.p.counter;
                                    tempBallot.value = newMessageBallots[j].value;
                                    isAgreed = checkAcceptedPrepare(tempBallot);
                                }
                            }
                        }
                    }
                }
            }
            else { /// Phase: SCPExternalize
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (validatorBallotState.c.value == newMessageBallots[j].value) {
                            isAgreed = checkAcceptedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                        }
                    }
                }
            }

            if (isAgreed) {
                hasNewAcceptedPrepare = true;
                if (
                    acceptedBallot.counter < tempBallot.counter
                    || (acceptedBallot.counter == tempBallot.counter
                        && isLessValue(acceptedBallot.value, tempBallot.value)) // acceptedBallot.value < tempBallot.value
                ) {
                    acceptedBallot.counter = tempBallot.counter;
                    acceptedBallot.value = tempBallot.value;
                }
            }
        }
    }

    return hasNewAcceptedPrepare;
}

bool checkConfirmedPrepareQuorum(int[0,N] nodeID, const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;

    SCPQuorumSet nodeQuorumSet = qs[nodeID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        if (N - id + cntQuorumTH < nodeQuorumSet.threshold) {
            return false;
        }

        validatorID = nodeQuorumSet.validators[id];

        if (validatorID != N) {
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                if (
                    ( // p
                        validatorBallotState.p.counter != 0
                        && (validatorBallotState.p.value == candidate.value
                            && validatorBallotState.p.counter >= candidate.counter)
                    )
                    || ( // pp
                        validatorBallotState.pp.counter != 0
                        && (validatorBallotState.pp.value == candidate.value
                            && validatorBallotState.pp.counter >= candidate.counter)
                    )
                ) {
                    cntQuorumTH++;
                }
            }
            else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                if (validatorBallotState.p.value == candidate.value
                    && validatorBallotState.p.counter >= candidate.counter) {
                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if (validatorBallotState.c.value == candidate.value) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= nodeQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkConfirmedPrepare(const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;

    SCPQuorumSet myQuorumSet = qs[myID];
    int[0,N] validatorID;

    for (id : int[0,N-1]) {
        if (N - id + cntQuorumTH < myQuorumSet.threshold) {
            return false;
        }

        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            if (checkConfirmedPrepareQuorum(validatorID, candidate)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= myQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptConfirmPrepare(SCPBallot &confirmedHBallot, SCPBallot &newMessageBallots[3]) {
    bool isAgreed = false;
    bool hasNewConfirmedPrepare = false;
    SCPBallot tempBallot;

    SCPQuorumSet myQuorumSet = qs[myID];
    SCPBallotState myBallotState = ballotStates[myID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            isAgreed = false;
            tempBallot.counter = 0;
            tempBallot.value = NOVALUE;
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if ( // p
                            validatorBallotState.p.counter != 0
                            && (validatorBallotState.p.value == newMessageBallots[j].value
                                && validatorBallotState.p.counter <= newMessageBallots[j].counter)
                        ) {
                            isAgreed = checkConfirmedPrepare(validatorBallotState.p);
                            if (isAgreed) {
                                tempBallot.counter = validatorBallotState.p.counter;
                                tempBallot.value = validatorBallotState.p.value;
                            } else {
                                if ( // pp
                                    validatorBallotState.pp.counter != 0
                                    && (validatorBallotState.pp.value == newMessageBallots[j].value
                                        && validatorBallotState.pp.counter <= newMessageBallots[j].counter)) {

                                    isAgreed = checkConfirmedPrepare(validatorBallotState.pp);
                                    if (isAgreed) {
                                        tempBallot.counter = validatorBallotState.pp.counter;
                                        tempBallot.value = validatorBallotState.pp.value;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (validatorBallotState.p.counter < newMessageBallots[j].counter) {
                            tempBallot.counter = validatorBallotState.p.counter;
                            tempBallot.value = newMessageBallots[j].value;
                            isAgreed = checkConfirmedPrepare(tempBallot);
                        }
                    }
                }
            }
            else { /// Phase: SCPExternalize
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (validatorBallotState.c.value == newMessageBallots[j].value) {
                            isAgreed = checkConfirmedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                        }
                    }
                }
            }

            if (isAgreed) {
                if (myBallotState.h.counter == 0
                    || (myBallotState.h.counter < tempBallot.counter
                        || (myBallotState.h.counter == tempBallot.counter
                            && isLessValue(myBallotState.h.value, tempBallot.value)))) { // myBallotState.h.value < tempBallot.value

                    hasNewConfirmedPrepare = true;
                    if (confirmedHBallot.counter == 0) {
                        confirmedHBallot.counter = tempBallot.counter;
                        confirmedHBallot.value = tempBallot.value;
                    } else {
                        if (confirmedHBallot.counter < tempBallot.counter
                            || (confirmedHBallot.counter == tempBallot.counter
                                && isLessValue(confirmedHBallot.value, tempBallot.value))) { // confirmedHBallot.value < tempBallot.value

                            confirmedHBallot.counter = tempBallot.counter;
                            confirmedHBallot.value = tempBallot.value;
                        }
                    }
                }
            }
        }
    }

    return hasNewConfirmedPrepare;
}

bool checkAcceptedCommitQuorum(int[0,N] nodeID, const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntQuorumTH = 0;
    bool isVBlocked = false;

    SCPQuorumSet nodeQuorumSet = qs[nodeID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        if (N - id + cntQuorumTH < nodeQuorumSet.threshold) {
            return false;
        }

        validatorID = nodeQuorumSet.validators[id];

        if (validatorID != N) {
            isVBlocked = false;
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                if (validatorBallotState.b.value == ballotValue
                    && validatorBallotState.h.counter >= counterH) {
                    cntQuorumTH++;
                }
            }
            else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                if (validatorBallotState.b.value == ballotValue
                    && (validatorBallotState.c.counter <= counterC
                        && validatorBallotState.h.counter >= counterH)) {

                    cntQuorumTH++;
                    isVBlocked = true;
                }
                if (!isVBlocked
                    && (validatorBallotState.b.value == ballotValue
                        && validatorBallotState.c.counter <= counterC)) {

                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if (validatorBallotState.c.value == ballotValue
                    && validatorBallotState.c.counter <= counterC) {

                    cntQuorumTH++;
                    isVBlocked = true;
                }
                if (!isVBlocked
                    && (validatorBallotState.c.value == ballotValue
                        && validatorBallotState.c.counter <= counterC)) {

                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= nodeQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkAcceptedCommit(const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntVBlockTH = 0;
    int[0,N] cntQuorumTH = 0;

    SCPQuorumSet myQuorumSet = qs[myID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                // do nothing
            } else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                if (validatorBallotState.b.value == ballotValue
                    && (validatorBallotState.c.counter <= counterC
                        && validatorBallotState.h.counter >= counterH)) {
                    cntVBlockTH++;
                }
            } else { /// Phase: SCPExternalize
                if (validatorBallotState.c.value == ballotValue
                    && validatorBallotState.c.counter <= counterC) {
                    cntVBlockTH++;
                }
            }

            if (cntVBlockTH > getTotalValidators(myID) - myQuorumSet.threshold) {
                return true;
            }

            if (checkAcceptedCommitQuorum(validatorID, ballotValue, counterC, counterH)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= myQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptAcceptCommit(SCPBallot &newMessageBallots[3], int[0,INFINITY] &acceptedCounterC, int[0,INFINITY] &acceptedCounterH) {
    int[0,N*3] k; // index for curBoundaries[N*3]
    int[0,INFINITY] curBoundaries[N*3];
    int[0,N*3] nextBoundary = 0;
    bool isAgreed = false;

    SCPQuorumSet myQuorumSet = qs[myID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare /// Phase: SCPPrepare
                && validatorBallotState.b.value == newMessageBallots[0].value
            ) {
                if (validatorBallotState.c.counter != 0) { // c
                    curBoundaries[nextBoundary++] = validatorBallotState.c.counter;
                }
                if (validatorBallotState.h.counter != 0) { // h
                    curBoundaries[nextBoundary++] = validatorBallotState.h.counter;
                }

            } else if (validatorBallotState.curState == SCPConfirm /// Phase: SCPConfirm
                && validatorBallotState.b.value == newMessageBallots[0].value
            ) {
                curBoundaries[nextBoundary++] = validatorBallotState.c.counter;
                curBoundaries[nextBoundary++] = validatorBallotState.h.counter;

            } else { /// Phase: SCPExternalize
                if (validatorBallotState.c.value == newMessageBallots[0].value) {
                    curBoundaries[nextBoundary++] = validatorBallotState.c.counter;
                    curBoundaries[nextBoundary++] = validatorBallotState.h.counter;
                    curBoundaries[nextBoundary++] = INFINITY;
                }
            }
        }
    }

    // sort curBoundaries[0 .. nextBoundary-1]: highest first
    sortArr(nextBoundary, curBoundaries);

    k = 0;
    acceptedCounterC = 0;
    acceptedCounterH = 0;
    isAgreed = false;
    do {
        if (acceptedCounterH == 0) {// find the high boundary
            if (
                checkAcceptedCommit(newMessageBallots[0].value, curBoundaries[k], curBoundaries[k])
            ) {
                isAgreed = true;
                acceptedCounterH = curBoundaries[k];
                k++;
            } else {
                k++;
            }
        } else {// find the low boundary
            if (
                checkAcceptedCommit(newMessageBallots[0].value, curBoundaries[k], acceptedCounterH)
            ) {
                acceptedCounterC = curBoundaries[k];
                k = nextBoundary;
            } else {
                k++;
            }
        }
    } while (acceptedCounterC == 0 && k < nextBoundary);

    return isAgreed;
}

bool checkConfirmedCommitQuorum(int[0,N] nodeID, const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntQuorumTH = 0;

    SCPQuorumSet nodeQuorumSet = qs[nodeID];
    int[0,N] validatorID;
    SCPBallotState validatorBallotState;

    for (id : int[0,N-1]) {
        if (N - id + cntQuorumTH < nodeQuorumSet.threshold) {
            return false;
        }

        validatorID = nodeQuorumSet.validators[id];

        if (validatorID != N) {
            validatorBallotState = ballotStates[validatorID];

            if (validatorBallotState.curState == SCPPrepare) { /// Phase: SCPPrepare
                // do nothing
            } else if (validatorBallotState.curState == SCPConfirm) { /// Phase: SCPConfirm
                if (validatorBallotState.b.value == ballotValue
                    && validatorBallotState.c.counter <= counterC
                    && validatorBallotState.h.counter >= counterH) {
                    cntQuorumTH++;
                }
            } else { /// Phase: SCPExternalize
                if (validatorBallotState.c.value == ballotValue
                    && validatorBallotState.c.counter <= counterC) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= nodeQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkConfirmedCommit(const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntQuorumTH = 0;

    SCPQuorumSet myQuorumSet = qs[myID];
    int[0,N] validatorID;

    for (id : int[0,N-1]) {
        validatorID = myQuorumSet.validators[id];

        if (validatorID != N) {
            if (N - id + cntQuorumTH < myQuorumSet.threshold) {
                return false;
            }

            if (checkConfirmedCommitQuorum(validatorID, ballotValue, counterC, counterH)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= myQuorumSet.threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptConfirmCommit(SCPBallot &newMessageBallots[3], int[0,INFINITY] &acceptedCounterC, int[0,INFINITY] &acceptedCounterH) {
    int[0,N*3] k; // index for curBoundaries[N*3]
    int[0,INFINITY] curBoundaries[N*3];
    int[0,N*3] nextBoundary = 0;
    bool isAgreed = false;

    for (n : int[0,N-1]) {
        if (qs[myID].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[myID].validators[n]
                ].curState == SCPPrepare
            ) {
                // do nothing
            } else if ( /// Phase: SCPConfirm
                ballotStates[
                    qs[myID].validators[n]
                ].curState == SCPConfirm
                && ballotStates[qs[myID].validators[n]].b.value == newMessageBallots[0].value
            ) {

                curBoundaries[nextBoundary++] = ballotStates[qs[myID].validators[n]].c.counter;
                curBoundaries[nextBoundary++] = ballotStates[qs[myID].validators[n]].h.counter;
            } else { /// Phase: SCPExternalize

                if (ballotStates[qs[myID].validators[n]].c.value == newMessageBallots[0].value) {
                    curBoundaries[nextBoundary++] = ballotStates[qs[myID].validators[n]].c.counter;
                    curBoundaries[nextBoundary++] = ballotStates[qs[myID].validators[n]].h.counter;
                    curBoundaries[nextBoundary++] = INFINITY;
                }
            }
        }
    }

    // sort curBoundaries[0 .. nextBoundary-1]: highest first
    sortArr(nextBoundary, curBoundaries);

    k = 0;
    acceptedCounterC = 0;
    acceptedCounterH = 0;
    isAgreed = false;
    do {
        if (acceptedCounterH == 0) {// find the high boundary
            if (
                checkConfirmedCommit(newMessageBallots[0].value, curBoundaries[k], curBoundaries[k])
            ) {
                isAgreed = true;
                acceptedCounterH = curBoundaries[k];
                k++;
            } else {
                k++;
            }
        } else {// find the low boundary
            if (
                checkConfirmedCommit(newMessageBallots[0].value, curBoundaries[k], acceptedCounterH)
            ) {
                acceptedCounterC = curBoundaries[k];
                k = nextBoundary;
            } else {
                k++;
            }
        }
    } while (acceptedCounterC == 0 && k < nextBoundary);

    return isAgreed;
}

/// ----- ** Ballot FUNCTIONS
void initBallotState() {
    cur_b_cnt[myID] = 1;
    ballotStates[myID].b.counter = 1;

    for (v : v_id) {
        if (nominatedValues[myID][v] == true 
        && ballotStates[myID].b.value[v] == false) {
            ballotStates[myID].b.value[v] = true;
            return;
        }
    }
}

void resetBallotState() {
    cur_b_cnt[myID] = 0;
    tickBallot[myID] = 0;
    ballotDone[myID] = false;

    ballotStates[myID].curState = SCPPrepare;
    ballotStates[myID].b.counter = 0;
    ballotStates[myID].b.value = NOVALUE;
    ballotStates[myID].p.counter = 0;
    ballotStates[myID].p.value = NOVALUE;
    ballotStates[myID].pp.counter = 0;
    ballotStates[myID].pp.value = NOVALUE;
    ballotStates[myID].h.counter = 0;
    ballotStates[myID].h.value = NOVALUE;
    ballotStates[myID].c.counter = 0;
    ballotStates[myID].c.value = NOVALUE;
}

void updateBValue() {
    if (ballotStates[myID].h.value != NOVALUE) {
        // if `h` is NOT empty
        ballotStates[myID].b.value = ballotStates[myID].h.value;

    } else if (nominatedValues[myID] != NOVALUE) {

        for (v : v_id) {
            if (nominatedValues[myID][v] == true 
                && ballotStates[myID].b.value[v] == false) {

                ballotStates[myID].b.value[v] = true;
                return;
            }
        }
    }
    else if (ballotStates[myID].p.value != NOVALUE) {
        // if `p` is NOT empty
        ballotStates[myID].b.value = ballotStates[myID].p.value;
    }
}

void processMessagePrepare() {
    bool hasNewBallot = false;
    int[0,N-1] newMessageNode = myID;
    int[0,N-1] newMessageNodeIndex = 0;
    int[0,N] current = 0;
    int[0,INFINITY] acceptedCounterC = 0;
    int[0,INFINITY] acceptedCounterH = 0;
    SCPBallot newBallot;
    SCPBallot newMessageBallots[3]; // to store 3 ballots used at each phase

    newMessageNodeIndex = cur_b_cnt[myID] % getTotalValidators(myID);

    // update newMessageNode
    for (n : n_id) {
        if (qs[myID].validators[n] != N) {
            if (current == newMessageNodeIndex) {
                newMessageNode = qs[myID].validators[n];
            } else {
                current++;
            }
        }
    }

    // if new message is not valid, return.
    if (ballotStates[qs[myID].validators[newMessageNode]].b.counter < ballotStates[myID].b.counter) {
        return;
    }

    // set newMessageBallots
    if (ballotStates[newMessageNode].curState == SCPPrepare) {
        /// Phase: SCPPrepare
        // b
        newMessageBallots[0].counter = ballotStates[newMessageNode].b.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        // p
        newMessageBallots[1].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[1].value = ballotStates[newMessageNode].p.value;
        // p'
        newMessageBallots[2].counter = ballotStates[newMessageNode].pp.counter;
        newMessageBallots[2].value = ballotStates[newMessageNode].pp.value;

    } else if (ballotStates[newMessageNode].curState == SCPConfirm) {
        /// Phase: SCPConfirm
        // p.n, b.x
        newMessageBallots[0].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        // INFINITY, b.x
        newMessageBallots[1].counter = INFINITY;
        newMessageBallots[1].value = ballotStates[newMessageNode].b.value;
        // 0, NULL
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;

    } else {
        /// Phase: SCPExternalize
        // INFINITY, c.x
        newMessageBallots[0].counter = INFINITY;
        newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        // 0, NULL
        newMessageBallots[1].counter = 0;
        newMessageBallots[1].value = NOVALUE;
        // 0, NULL
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;
    }

    // blocking threshold check for b.counter

    // blocking threshold check for accept prepare ballots (attemptAcceptPrepare)
    // quorum threshold check for vote prepare ballots (attemptAcceptPrepare)
    newBallot.counter = 0;
    newBallot.value = NOVALUE;
    hasNewBallot = attemptAcceptPrepare(newBallot, newMessageBallots);

    if (hasNewBallot) {
        // update p or pp
        if (ballotStates[myID].p.counter == 0) {
            ballotStates[myID].p.counter = newBallot.counter;
            ballotStates[myID].p.value = newBallot.value;
        } else {
            if (
                ballotStates[myID].p.counter < newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(ballotStates[myID].p.value, newBallot.value)) // ballotStates[myID].p.value < newBallot.value
            ) {

                if (ballotStates[myID].p.value != newBallot.value) {

                    ballotStates[myID].pp.counter = ballotStates[myID].p.counter;
                    ballotStates[myID].pp.value = ballotStates[myID].p.value;
                }

                ballotStates[myID].p.counter = newBallot.counter;
                ballotStates[myID].p.value = newBallot.value;

            } else if (
                ballotStates[myID].p.counter > newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(newBallot.value, ballotStates[myID].p.value)) // ballotStates[myID].p.value > newBallot.value
            ) { 
                if (
                    ballotStates[myID].pp.counter == 0
                    || (ballotStates[myID].pp.counter < newBallot.counter
                        || (ballotStates[myID].pp.counter == newBallot.counter
                            && isLessValue(ballotStates[myID].pp.value, newBallot.value))) // ballotStates[myID].pp.value < newBallot.value
                ) { 
                    if (ballotStates[myID].p.value != newBallot.value) {

                        ballotStates[myID].pp.counter = newBallot.counter;
                        ballotStates[myID].pp.value = newBallot.value;
                    }
                }
            }
        }

        // clear c if required
        if (ballotStates[myID].c.counter != 0
            && ballotStates[myID].h.counter != 0
            && ((ballotStates[myID].p.counter != 0
                    && ballotStates[myID].h.value != ballotStates[myID].p.value
                    && ballotStates[myID].h.counter < ballotStates[myID].p.counter)
                || (ballotStates[myID].pp.counter != 0
                    && ballotStates[myID].h.value != ballotStates[myID].pp.value
                    && ballotStates[myID].h.counter < ballotStates[myID].pp.counter))) {

            ballotStates[myID].c.counter = 0;
            ballotStates[myID].c.value = NOVALUE;
        }
    }

    // quorum threshold check for accept prepare ballots (attemptConfirmPrepare)
    if (ballotStates[myID].p.counter != 0) {
        newBallot.counter = 0;
        newBallot.value = NOVALUE;
        hasNewBallot = attemptConfirmPrepare(newBallot, newMessageBallots);

        if (hasNewBallot) {
            // update h or c
            if (newBallot.counter != 0) {
                ballotStates[myID].h.counter = newBallot.counter;
                ballotStates[myID].h.value = newBallot.value;
                if (ballotStates[myID].c.counter == 0
                    && (ballotStates[myID].p.counter == 0
                        || !(ballotStates[myID].p.value != newBallot.value
                            && ballotStates[myID].p.counter <= newBallot.counter))
                    && (ballotStates[myID].pp.counter == 0
                        || !(ballotStates[myID].pp.value != newBallot.value
                            && ballotStates[myID].pp.counter <= newBallot.counter))
                    && (ballotStates[myID].b.counter < newBallot.counter
                        || (ballotStates[myID].b.counter == newBallot.counter
                            && !isLessValue(newBallot.value, ballotStates[myID].b.value)))) { // ballotStates[myID].b.value <= newBallot.value

                    ballotStates[myID].c.counter = newBallot.counter;
                    ballotStates[myID].c.value = newBallot.value;
                }
            }

            // bump b if required
            if (ballotStates[myID].b.counter == 0
                || (ballotStates[myID].b.counter < ballotStates[myID].h.counter
                    || (ballotStates[myID].b.counter == ballotStates[myID].h.counter
                        && isLessValue(ballotStates[myID].b.value, ballotStates[myID].h.value)))) { // ballotStates[myID].b.value < ballotStates[myID].h.value

                ballotStates[myID].b.counter = ballotStates[myID].h.counter;
                ballotStates[myID].b.value = ballotStates[myID].h.value;
            }
        }
    }

    // blocking threshold check for accept commit ballots (attemptAcceptCommit)
    // quorum threshold check for vote commit ballots (attemptAcceptCommit)
    if (ballotStates[newMessageNode].h.counter != 0) {
        newMessageBallots[0].counter = ballotStates[newMessageNode].h.counter;

        if (/// Phase: SCPExternalize
            ballotStates[newMessageNode].curState == SCPExternalize
        ) {
            newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        } else {
            newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        }

        hasNewBallot = attemptAcceptCommit(newMessageBallots, acceptedCounterC, acceptedCounterH);

        if (hasNewBallot) {
            if (acceptedCounterC == 0) {
                acceptedCounterC = acceptedCounterH;
            }

            ballotStates[myID].c.counter = acceptedCounterC;
            ballotStates[myID].c.value = newMessageBallots[0].value;
            ballotStates[myID].h.counter = acceptedCounterH;
            ballotStates[myID].h.value = newMessageBallots[0].value;
            ballotStates[myID].curState = SCPConfirm;
            ballotStates[myID].pp.counter = 0;
            ballotStates[myID].pp.value = NOVALUE;
        }
    }

    if (ballotStates[myID].h.counter > ballotStates[myID].b.counter) {
        ballotStates[myID].b.counter = ballotStates[myID].h.counter;
        ballotStates[myID].b.value = ballotStates[myID].h.value;
    }
}

void processMessageCommit() {
    bool hasNewBallot = false;
    int[0,N-1] newMessageNode = myID;
    int[0,N-1] newMessageNodeIndex = 0;
    int[0,N] current = 0;
    int[0,INFINITY] acceptedCounterC = 0;
    int[0,INFINITY] acceptedCounterH = 0;
    SCPBallot newBallot;
    SCPBallot newMessageBallots[3];

    newMessageNodeIndex = cur_b_cnt[myID] % getTotalValidators(myID);

    // update newMessageNode
    for (n : n_id) {
        if (qs[myID].validators[n] != N) {
            if (current == newMessageNodeIndex) {
                newMessageNode = qs[myID].validators[n];
            } else {
                current++;
            }
        }
    }

    // if new message is not valid, return.
    if (ballotStates[qs[myID].validators[newMessageNode]].b.counter < ballotStates[myID].b.counter) {
        return;
    }

    // set newMessageBallots
    if ( /// Phase: SCPPrepare
        ballotStates[newMessageNode].curState == SCPPrepare
    ) {
        // b
        newMessageBallots[0].counter = ballotStates[newMessageNode].b.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        // p
        newMessageBallots[1].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[1].value = ballotStates[newMessageNode].p.value;
        // p'
        newMessageBallots[2].counter = ballotStates[newMessageNode].pp.counter;
        newMessageBallots[2].value = ballotStates[newMessageNode].pp.value;

    } else if ( /// Phase: SCPConfirm
        ballotStates[newMessageNode].curState == SCPConfirm
    ) {
        // p.n, b.x
        newMessageBallots[0].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        // INFINITY, b.x
        newMessageBallots[1].counter = INFINITY;
        newMessageBallots[1].value = ballotStates[newMessageNode].b.value;
        // 0, NULL
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;

    }
    else { /// Phase: SCPExternalize
        // INFINITY, c.x
        newMessageBallots[0].counter = INFINITY;
        newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        // 0, NULL
        newMessageBallots[1].counter = 0;
        newMessageBallots[1].value = NOVALUE;
        // 0, NULL
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;
    }

    // blocking threshold check for b.counter

    // blocking threshold check for accept prepare ballots (attemptAcceptPrepare)
    // quorum threshold check for vote prepare ballots (attemptAcceptPrepare)
    newBallot.counter = 0;
    newBallot.value = NOVALUE;
    hasNewBallot = attemptAcceptPrepare(newBallot, newMessageBallots);

    if (hasNewBallot) {
        // update p or pp
        if (ballotStates[myID].p.counter == 0) {

            ballotStates[myID].p.counter = newBallot.counter;
            ballotStates[myID].p.value = newBallot.value;
        } else {
            if (ballotStates[myID].p.counter < newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(ballotStates[myID].p.value, newBallot.value))) { // ballotStates[myID].p.value < newBallot.value

                if (ballotStates[myID].p.value != newBallot.value) {

                    ballotStates[myID].pp.counter = ballotStates[myID].p.counter;
                    ballotStates[myID].pp.value = ballotStates[myID].p.value;
                }

                ballotStates[myID].p.counter = newBallot.counter;
                ballotStates[myID].p.value = newBallot.value;

            } else if (ballotStates[myID].p.counter > newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(newBallot.value, ballotStates[myID].p.value))) { // ballotStates[myID].p.value > newBallot.value

                if (ballotStates[myID].pp.counter == 0
                    || (ballotStates[myID].pp.counter < newBallot.counter
                        || (ballotStates[myID].pp.counter == newBallot.counter
                            && isLessValue(ballotStates[myID].pp.value, newBallot.value)))) { // ballotStates[myID].pp.value < newBallot.value

                    if (ballotStates[myID].p.value != newBallot.value) {

                        ballotStates[myID].pp.counter = newBallot.counter;
                        ballotStates[myID].pp.value = newBallot.value;
                    }
                }
            }
        }
    }

    // blocking threshold check for accept commit ballots (attemptAcceptCommit)
    // quorum threshold check for vote commit ballots (attemptAcceptCommit)
    if (ballotStates[newMessageNode].h.counter != 0) {
        newMessageBallots[0].counter = ballotStates[newMessageNode].h.counter;

        if ( /// Phase: SCPExternalize
            ballotStates[newMessageNode].curState == SCPExternalize
        ) {
            newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        } else {
            newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        }

        hasNewBallot = attemptAcceptCommit(newMessageBallots, acceptedCounterC, acceptedCounterH);

        if (hasNewBallot) {
            if (acceptedCounterC == 0) {
                acceptedCounterC = acceptedCounterH;
            }

            ballotStates[myID].c.counter = acceptedCounterC;
            ballotStates[myID].c.value = newMessageBallots[0].value;
            ballotStates[myID].h.counter = acceptedCounterH;
            ballotStates[myID].h.value = newMessageBallots[0].value;
            ballotStates[myID].pp.counter = 0;
            ballotStates[myID].pp.value = NOVALUE;
        }
    }

    // quorum threshold check for accept commit ballots (attemptConfirmCommit)
    if ( // Phase not SCPPrepare
        ballotStates[newMessageNode].curState != SCPPrepare
    ) {

        newMessageBallots[0].counter = ballotStates[newMessageNode].h.counter;

        if ( /// Phase: SCPExternalize
            ballotStates[newMessageNode].curState == SCPExternalize
        ) {
            newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        } else { /// Phase: SCPConfirm
            newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        }

        hasNewBallot = attemptConfirmCommit(newMessageBallots, acceptedCounterC, acceptedCounterH);

        if (hasNewBallot) {
            if (acceptedCounterC == 0) {
                acceptedCounterC = acceptedCounterH;
            }

            ballotStates[myID].c.counter = acceptedCounterC;
            ballotStates[myID].c.value = newMessageBallots[0].value;
            ballotStates[myID].h.counter = acceptedCounterH;
            ballotStates[myID].h.value = newMessageBallots[0].value;
            ballotStates[myID].curState = SCPExternalize;
            ballotStates[myID].b.counter = INFINITY;
        }
    }

    if (ballotStates[myID].h.counter > ballotStates[myID].b.counter) {

        ballotStates[myID].b.counter = ballotStates[myID].h.counter;
        ballotStates[myID].b.value = ballotStates[myID].h.value;
    }
}

void newBCounter() {
    if (tickBallot[myID] == cur_b_cnt[myID]) {
        if ( /// Phase: SCPPrepare
            ballotStates[myID].curState == SCPPrepare
        ) {
            processMessagePrepare();

            if (ballotStates[myID].b.counter < BOUNDARY) {
                ballotStates[myID].b.counter++;
            }

            if (cur_b_cnt[myID] < BOUNDARY) {
                cur_b_cnt[myID]++;
            }

            updateBValue();

        } else if ( /// Phase: SCPConfirm
            ballotStates[myID].curState == SCPConfirm
        ) {
            processMessageCommit();

            if (ballotStates[myID].b.counter < BOUNDARY) {
                ballotStates[myID].b.counter++;
            }

            if (cur_b_cnt[myID] < BOUNDARY) {
                cur_b_cnt[myID]++;
            }
            updateBValue();
        }
        else {/// Phase: SCPExternalize
            // do nothing
        }

        tickBallot[myID] = 0;
    }

    if (tickBallot[myID] < cur_b_cnt[myID]) {
        tickBallot[myID]++;
    }
}

